effect.shader:
void main(){
    vec2 ctr = center/1000.0 + 0.5;
    vec2 d = acScreenNorm - ctr;
    d.x *= acScreenSize.x/acScreenSize.y;
    float r = length(d) + 0.001;
    float pull = mass*0.08 / r;
    float a = spin*pull*4.0;
    float s=sin(a), co=cos(a);
    vec2 dir = mat2(co,-s,s,co)*normalize(d);
    vec2 nd = dir*max(r - pull, 0.0);
    nd.x /= acScreenSize.x/acScreenSize.y;
    gl_FragColor = texture2DCv(inputImg.texture, ctr+nd);
}
